import{_ as t,o,c as n,a3 as a}from"./chunks/framework.qCVWde4n.js";const m=JSON.parse('{"title":"Bring your own key","description":"","frontmatter":{},"headers":[],"relativePath":"own-key.md","filePath":"own-key.md"}'),r={name:"own-key.md"};function s(i,e,d,h,l,c){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="bring-your-own-key" tabindex="-1">Bring your own key <a class="header-anchor" href="#bring-your-own-key" aria-label="Permalink to &quot;Bring your own key&quot;">​</a></h1><p>nanoMuse is free and non-profit. The model behind it costs money, and the developer pays for a starting allowance per account (the app shows the relay&#39;s current figures). When it is gone, there are two ways on that need nothing from nanoMuse: a key of your own at a model provider, or a plan you already pay for — ChatGPT, Claude, Kimi — signed in from the app.</p><p>Every client reads the same list of providers, with what each one covers: <strong>chat</strong>, <strong>the hands</strong> (a model that sees screenshots), <strong>pictures</strong> (the avatar studio) and <strong>clips</strong> (the avatar&#39;s short videos). A feature no configured provider covers is simply not offered, with one sentence saying which providers would — nothing breaks.</p><p>Your sign-in, your invite code and your devices are not affected: the account stays, only the model provider changes. Nothing you say passes through nanoMuse Cloud once your own key or plan is in use.</p><h2 id="where-you-are-decides-who-comes-first" tabindex="-1">Where you are decides who comes first <a class="header-anchor" href="#where-you-are-decides-who-comes-first" aria-label="Permalink to &quot;Where you are decides who comes first&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>First</th><th>What one key there covers</th></tr></thead><tbody><tr><td>Mainland China</td><td><strong>Alibaba Cloud Bailian</strong></td><td>chat, the hands, pictures and clips — all four under one key</td></tr><tr><td>Everywhere else</td><td><strong>OpenRouter</strong>, then <strong>OpenAI</strong></td><td>chat, the hands and pictures; clips are Bailian only for now</td></tr></tbody></table><p>Bailian only signs up accounts with a mainland Chinese identity; outside, one OpenRouter account puts hundreds of models behind one key, pay as you go. Beyond the first pick, every provider below works on its own or beside another — DeepSeek for the chat and Zhipu for pictures, say.</p><p>Four jobs, four settings, one page: <strong>Settings › Models</strong> on Android, the iPhone and the desktop, the <em>Connections</em> page in the web console. The rows are <em>Chat</em>, <em>Operating the screen</em>, <em>Making pictures</em> and <em>Making clips</em>; each shows <code>provider · model</code> and opens a picker that lists only the models that can do that job (the screen needs a model that sees images). On the iPhone the screen row is disabled (<em>Not on iPhone</em>): a phone cannot operate its own screen, and your computer uses its own setting. <a href="#which-model-does-what">Which model does what</a> below has the details.</p><h2 id="what-each-provider-covers" tabindex="-1">What each provider covers <a class="header-anchor" href="#what-each-provider-covers" aria-label="Permalink to &quot;What each provider covers&quot;">​</a></h2><p>Chat = the conversation; hands = reading screenshots to operate the phone or the computer; pictures = the avatar studio&#39;s images; clips = the avatar&#39;s short videos.</p><table tabindex="0"><thead><tr><th>Provider</th><th style="text-align:center;">Chat</th><th style="text-align:center;">Hands</th><th style="text-align:center;">Pictures</th><th style="text-align:center;">Clips</th><th>Region</th><th>Make a key</th></tr></thead><tbody><tr><td>Alibaba Cloud Bailian</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td>mainland China</td><td><a href="https://bailian.console.aliyun.com/?apiKey=1" target="_blank" rel="noreferrer">bailian.console.aliyun.com</a></td></tr><tr><td>DeepSeek</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>both</td><td><a href="https://platform.deepseek.com/api_keys" target="_blank" rel="noreferrer">platform.deepseek.com</a></td></tr><tr><td>Kimi (Moonshot AI)</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>both (a mainland and a global edition)</td><td><a href="https://platform.moonshot.cn/console/api-keys" target="_blank" rel="noreferrer">platform.moonshot.cn</a> · <a href="https://platform.kimi.ai/console" target="_blank" rel="noreferrer">platform.kimi.ai</a></td></tr><tr><td>Zhipu GLM</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>mainland China</td><td><a href="https://open.bigmodel.cn/usercenter/apikeys" target="_blank" rel="noreferrer">open.bigmodel.cn</a></td></tr><tr><td>SiliconFlow</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>mainland China</td><td><a href="https://cloud.siliconflow.cn/account/ak" target="_blank" rel="noreferrer">cloud.siliconflow.cn</a></td></tr><tr><td>Volcengine Ark (Doubao)</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>mainland China</td><td><a href="https://console.volcengine.com/ark/region:ark+cn-beijing/apiKey" target="_blank" rel="noreferrer">console.volcengine.com</a></td></tr><tr><td>MiniMax</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>both (a mainland and a global edition)</td><td><a href="https://platform.minimaxi.com/user-center/basic-information/interface-key" target="_blank" rel="noreferrer">platform.minimaxi.com</a></td></tr><tr><td>OpenRouter</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>outside mainland China</td><td><a href="https://openrouter.ai/keys" target="_blank" rel="noreferrer">openrouter.ai/keys</a></td></tr><tr><td>OpenAI</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>outside mainland China</td><td><a href="https://platform.openai.com/api-keys" target="_blank" rel="noreferrer">platform.openai.com</a></td></tr><tr><td>Anthropic Claude</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>outside mainland China</td><td><a href="https://platform.claude.com/settings/keys" target="_blank" rel="noreferrer">platform.claude.com</a></td></tr><tr><td>Google Gemini</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>outside mainland China</td><td><a href="https://aistudio.google.com/apikey" target="_blank" rel="noreferrer">aistudio.google.com</a></td></tr><tr><td>xAI Grok</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td>outside mainland China</td><td><a href="https://console.x.ai" target="_blank" rel="noreferrer">console.x.ai</a></td></tr><tr><td>Groq</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>outside mainland China</td><td><a href="https://console.groq.com/keys" target="_blank" rel="noreferrer">console.groq.com</a></td></tr><tr><td>Mistral AI</td><td style="text-align:center;">●</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>outside mainland China</td><td><a href="https://console.mistral.ai/api-keys" target="_blank" rel="noreferrer">console.mistral.ai</a></td></tr><tr><td>Ollama / LM Studio / vLLM (on your machine)</td><td style="text-align:center;">●</td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td>both</td><td>no key</td></tr></tbody></table><p>Only Bailian has a dot under <em>Clips</em> because nanoMuse&#39;s clip generation speaks Bailian&#39;s video API; the other vendors&#39; video models sit behind their own task APIs, not wired this round. Under <em>Pictures</em>, OpenRouter goes through its Image API with models such as <code>openai/gpt-image-2</code>; Gemini uses <code>gemini-2.5-flash-image</code>.</p><p>The table is the repository&#39;s catalogue, <a href="https://github.com/nano-muse/nanoMuse/blob/main/nanomuse/llm/providers.json" target="_blank" rel="noreferrer"><code>nanomuse/llm/providers.json</code></a> — every client and the relay read it; endpoints, default models and what each covers are in there, checked against each vendor&#39;s documentation in October 2026.</p><h2 id="making-a-key" tabindex="-1">Making a key <a class="header-anchor" href="#making-a-key" aria-label="Permalink to &quot;Making a key&quot;">​</a></h2><p>The same three steps everywhere: sign up → create an API key in the console → paste it into nanoMuse. <strong>The key is for nanoMuse only; never send it to anyone or paste it into a chat.</strong></p><ul><li><strong>Alibaba Cloud Bailian.</strong> Sign in to <a href="https://bailian.console.aliyun.com/" target="_blank" rel="noreferrer">bailian.console.aliyun.com</a> with an Alibaba Cloud account (identity verification is required), accept <em>Enable Model Studio</em> on first entry, then create a key on the <a href="https://bailian.console.aliyun.com/?apiKey=1" target="_blank" rel="noreferrer">API-KEY page</a>; it starts with <code>sk-</code>. A new account comes with free tokens for a while. Set a usage alert in the console.</li><li><strong>DeepSeek.</strong> Sign up, add credit and create a key at <a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">platform.deepseek.com</a>; base URL <code>https://api.deepseek.com/v1</code>.</li><li><strong>Kimi.</strong> The mainland edition is <a href="https://platform.moonshot.cn/console/api-keys" target="_blank" rel="noreferrer">platform.moonshot.cn</a>, base URL <code>https://api.moonshot.cn/v1</code>; the global one is <a href="https://platform.kimi.ai/console" target="_blank" rel="noreferrer">platform.kimi.ai</a>, base URL <code>https://api.moonshot.ai/v1</code>. Accounts and keys are not shared between the two.</li><li><strong>Zhipu GLM.</strong> <a href="https://open.bigmodel.cn/usercenter/apikeys" target="_blank" rel="noreferrer">open.bigmodel.cn</a>, base URL <code>https://open.bigmodel.cn/api/paas/v4</code>.</li><li><strong>SiliconFlow.</strong> <a href="https://cloud.siliconflow.cn/account/ak" target="_blank" rel="noreferrer">cloud.siliconflow.cn</a>, base URL <code>https://api.siliconflow.cn/v1</code>; model ids carry the vendor prefix, e.g. <code>deepseek-ai/DeepSeek-V4-Flash</code>.</li><li><strong>Volcengine Ark.</strong> <a href="https://console.volcengine.com/ark/region:ark+cn-beijing/apiKey" target="_blank" rel="noreferrer">console.volcengine.com</a> — enable the models you want in Ark, then create a key; base URL <code>https://ark.cn-beijing.volces.com/api/v3</code>.</li><li><strong>MiniMax.</strong> Mainland edition at <a href="https://platform.minimaxi.com/user-center/basic-information/interface-key" target="_blank" rel="noreferrer">platform.minimaxi.com</a>, base URL <code>https://api.minimaxi.com/v1</code>; the global base URL is <code>https://api.minimax.io/v1</code>.</li><li><strong>OpenRouter.</strong> Sign in at <a href="https://openrouter.ai/" target="_blank" rel="noreferrer">openrouter.ai</a> with Google, GitHub or an e-mail address, add credit under <em>Credits</em>, create a key under <em>Keys</em>; it starts with <code>sk-or-v1-</code>. <em>Settings → Limits</em> puts a monthly cap on a key.</li><li><strong>OpenAI.</strong> <a href="https://platform.openai.com/api-keys" target="_blank" rel="noreferrer">platform.openai.com</a>, base URL <code>https://api.openai.com/v1</code>.</li><li><strong>Anthropic.</strong> <a href="https://platform.claude.com/settings/keys" target="_blank" rel="noreferrer">platform.claude.com</a>. nanoMuse speaks Anthropic&#39;s own API; no compatibility layer is needed.</li><li><strong>Google Gemini.</strong> <a href="https://aistudio.google.com/apikey" target="_blank" rel="noreferrer">aistudio.google.com/apikey</a>, base URL <code>https://generativelanguage.googleapis.com/v1beta/openai</code>.</li><li><strong>xAI, Groq, Mistral.</strong> A key from each console; base URLs <code>https://api.x.ai/v1</code>, <code>https://api.groq.com/openai/v1</code>, <code>https://api.mistral.ai/v1</code>.</li></ul><p><strong>Paste it into nanoMuse.</strong></p><ul><li>Phone: <em>Set it up</em> on the allowance card opens the provider form pre-filled; or <em>Settings → Providers → Add</em>, pick the provider, paste the key, save.</li><li>Desktop: <em>Set it up</em> on the allowance card opens <em>Settings → nanoMuse Cloud</em> at the provider&#39;s row; or paste the key on that provider&#39;s row under <em>Ways on</em> there. The address is already filled in.</li><li>Web console: <em>Set it up</em> on the allowance card opens <em>Connections</em> with the provider chosen; or <em>Connections → Chat model</em>, click the provider, paste the key, save.</li><li>A runtime of your own: <code>[llm] provider = &quot;bailian&quot;</code> (any id from the table) and <code>api_key</code> in <code>config.toml</code>; the address and the default model fill in from the catalogue. Pictures or clips from another provider are an <code>[image]</code> / <code>[video]</code> block (<a href="./configuration#image-and-video">configuration.md</a>).</li></ul><p><strong>Use it for.</strong> Once the key is saved, a card asks what this key should handle: one switch per job the provider can do (chat, operating the screen, making pictures, making clips), all on. <em>Use it</em> moves those rows to this provider, on the catalogue&#39;s default model for each job (or the first model of its list that fits); <em>Not now</em> changes nothing, and so does a switch you turned off. Signed in, the card says nanoMuse Cloud keeps the rest. Every row can be changed later under <em>Settings › Models</em> (web console: <em>Connections</em>).</p><h2 id="which-model-does-what" tabindex="-1">Which model does what <a class="header-anchor" href="#which-model-does-what" aria-label="Permalink to &quot;Which model does what&quot;">​</a></h2><p><em>Settings › Models</em> (Android: the card at the top of Settings; iPhone: the first card of Settings; desktop: right after General; web console: the <em>Chat model</em>, <em>Hands model</em>, <em>Making pictures</em> and <em>Making clips</em> cards on <em>Connections</em>) has one row per job:</p><table tabindex="0"><thead><tr><th>Row</th><th>What it does</th><th>Who is listed</th></tr></thead><tbody><tr><td>Chat</td><td>The model that talks with you.</td><td>nanoMuse Cloud&#39;s chat models while signed in and switched on, then every provider of yours with chat models</td></tr><tr><td>Operating the screen</td><td>Looks at the screen and acts for you. Needs a model that can see images.</td><td>nanoMuse Cloud&#39;s hands model, then your providers&#39; models that see images; disabled on the iPhone (<em>Not on iPhone</em>)</td></tr><tr><td>Making pictures</td><td>Portraits of your Muse and the pictures you ask for.</td><td>nanoMuse Cloud, then your providers with image models</td></tr><tr><td>Making clips</td><td>Short clips of your Muse.</td><td>nanoMuse Cloud, then your providers with video models (Bailian)</td></tr></tbody></table><p>Each row shows <code>provider · model</code> and opens a picker: the <em>nanoMuse Cloud</em> group first while signed in, its recommended model marked, then one group per provider of yours holding only the models that fit. A provider without the capability does not appear in that row at all. A row nothing covers shows the one sentence naming who could, and <em>Add a provider</em>. A chat pick is the default for new chats and moves the main chat (<em>Applies to the main chat and to new chats; a side chat keeps its model.</em>): the main chat is the one conversation the Chat tab always shows and is never new, so it would otherwise stay on the provider it started with; a side chat already open keeps its model. The same on the phones and the desktop.</p><p><strong>Automatic.</strong> The screen, pictures and clips rows open with an <em>Automatic</em> entry that says what it gives right now (<em>Currently nanoMuse Cloud · qwen3.8-27b</em>, say). Pick it and the row forgets any choice made there and follows one order: the chat model&#39;s provider when it is one of yours and can do the job (its catalogue default), else nanoMuse Cloud while signed in and switched on, else the first provider of yours that can. A choice you made always wins; nanoMuse Cloud never steps in front of a provider you chose. Each device keeps its own choice, because keys never leave the device where they were entered.</p><p><strong>No silent fallback.</strong> When a model of your own fails under a turn, nothing switches by itself: the error card offers <em>Use nanoMuse Cloud this time</em> (signed in only), which runs that one turn on the account&#39;s model and changes no row. The desktop shows the same button after a failed studio round and a failed set of clips.</p><p><strong>Switching nanoMuse Cloud off.</strong> While signed in, the Models page has one switch, <em>Use nanoMuse Cloud models</em>. Off, the Cloud leaves the pickers and the automatic order, no side call (a chat&#39;s title, memory, a portrait, the hands) runs on it, and the only thing that spends your allowance is the <em>Use nanoMuse Cloud this time</em> button, each time you tap it. You stay signed in: sync, your devices and the account page keep working. The Cloud provider cannot be deleted the way one of yours can (deleting it was the same as signing out); signing out is under <em>Settings › nanoMuse Cloud</em>.</p><p><strong>Without an account.</strong> With a key of your own the app works signed out: chat, the hands, pictures and clips run on your providers, and the first screen offers <em>Use your own API key instead</em> next to the sign-in. The sign-in is needed only for nanoMuse Cloud&#39;s models, conversation sync and your devices reaching each other.</p><p><strong>Known limits.</strong> On the iPhone the pictures and clips rows list, besides nanoMuse Cloud, only your providers on a DashScope host (Alibaba Cloud Bailian); a key the catalogue says can draw (OpenRouter, OpenAI, Gemini, a custom endpoint) is named in one sentence under the picker, <em>Not offered here: …</em>, with where it does work, so you know the phone has not lost it. On the desktop the hands speak OpenAI&#39;s shape, so an Anthropic or native Gemini key is named under the screen row and not listed; a hands change takes effect at the hands&#39; next step, no restart. Pictures through a Gemini key go through Google&#39;s OpenAI-compatible layer: <code>images/generations</code> accepts <code>gemini-2.5-flash-image</code>, but Google&#39;s page does not document <code>images/edits</code> there, so the pose pictures of the avatar studio may not work with a Gemini key.</p><h2 id="sign-in-with-a-plan-you-already-pay-for" tabindex="-1">Sign in with a plan you already pay for <a class="header-anchor" href="#sign-in-with-a-plan-you-already-pay-for" aria-label="Permalink to &quot;Sign in with a plan you already pay for&quot;">​</a></h2><p>Some plans sign in directly, with no key to make:</p><table tabindex="0"><thead><tr><th>Plan</th><th>Covers</th><th>Where the sign-in is</th></tr></thead><tbody><tr><td><strong>ChatGPT</strong> (Plus / Pro / Team)</td><td>chat, the hands</td><td>Android, iPhone, desktop, web</td></tr><tr><td><strong>Claude</strong> (Pro / Max)</td><td>chat, the hands</td><td>Android, iPhone</td></tr><tr><td><strong>Kimi</strong></td><td>chat, the hands</td><td>Android, iPhone (device code)</td></tr><tr><td><strong>OpenRouter</strong></td><td>chat, the hands, pictures</td><td>Android, iPhone (one tap; the key comes back to the app)</td></tr></tbody></table><p>The ChatGPT sign-in uses the authorisation flow of OpenAI&#39;s own Codex (web console: <em>Connections → Or sign in with a ChatGPT plan</em>; desktop: the ChatGPT row under <em>Settings → nanoMuse Cloud</em>; phone: <em>Settings → Providers → OpenAI → Sign in</em>). Signed in, it covers chat and the hands only: the Codex backend has no image or video endpoints, so pictures and clips still want a key.</p><p>From a terminal it is the same flow: <code>nanomuse chatgpt login</code> opens the page and waits for the browser to come back, <code>nanomuse chatgpt status</code> says who is signed in and until when, <code>nanomuse chatgpt logout</code> forgets it; then <code>[llm] provider = &quot;chatgpt&quot;</code> in <code>config.toml</code> (no <code>base_url</code>, no <code>api_key</code>; an empty <code>model</code> is <code>gpt-5.6-sol</code>). The browser has to reach port 1455 on the machine the runtime runs on; when the runtime is elsewhere, copy the whole address the browser ends on and give it to the CLI&#39;s prompt or to <code>POST /api/chatgpt/callback {&quot;url&quot;: …}</code> (<a href="./configuration#a-chatgpt-plan-instead-of-a-key">configuration.md</a>).</p><p><strong>One honest line.</strong> OpenAI&#39;s terms cover using a ChatGPT plan inside OpenAI&#39;s own Codex; other apps have had this access cut off before (OpenCode, January 2026). If it stops working, an API key does.</p><h2 id="when-the-provider-cannot-be-reached" tabindex="-1">When the provider cannot be reached <a class="header-anchor" href="#when-the-provider-cannot-be-reached" aria-label="Permalink to &quot;When the provider cannot be reached&quot;">​</a></h2><p>Some networks do not get to <code>chatgpt.com</code> at all (the name does not resolve, the connection times out, TLS fails, an HTML interception page comes back where JSON was due), and in some regions OpenAI refuses outright (HTTP 403 <code>unsupported_country_region_territory</code>). The chat on the phone then shows a card, not the socket&#39;s words: what happened (<em>chatgpt.com cannot be reached from this network</em> or <em>OpenAI does not serve this region</em>), what helps (a VPN on this phone; the app&#39;s own proxy under <em>Settings → Network</em>; another provider with a key of your own), a <em>Try again</em> button, and the raw line behind <em>Details</em> for a bug report. An expired sign-in (401) reads <em>The ChatGPT sign-in is no longer valid</em> with <em>Sign in again</em>; a plan whose window is spent (a 429 that names a usage limit) reads <em>The ChatGPT plan has nothing left for now</em> with OpenAI&#39;s own sentence and when it resets; any other 429 is <em>Too many requests at once</em>. A key of your own that meets the same network trouble gets the same card with that provider&#39;s host in it.</p><p><strong>Settings → Network → HTTP proxy for own providers</strong> (Android and iPhone): host, port, an optional user name and password; off by default, kept on this phone only. Only the requests to the providers you added with your own key and to the ChatGPT plan go through it; nanoMuse Cloud, your computers and the local network never do. A <em>Test</em> row fetches <code>https://chatgpt.com/</code> through the proxy as entered and says whether it got through and in how many milliseconds. The same setting lives where each app keeps its keys: the phones have it in the provider form; the desktop under <strong>Settings → nanoMuse Cloud → Network</strong>, one address (<code>http://host:port</code> or <code>socks5://host:port</code>) that the app applies to its host process at the next start — <em>Restart now</em> is under the row — so every own key, the ChatGPT sign-in, the hands&#39; runtime and whatever else the app sends out go through it, and nanoMuse Cloud never does (<a href="./desktop">desktop.md</a>); the web app has the <em>Proxy</em> field in the own-key form; the runtime has <code>[llm] proxy</code> in <code>config.toml</code> (<a href="./configuration#llm">configuration.md</a>).</p><h2 id="local-models" tabindex="-1">Local models <a class="header-anchor" href="#local-models" aria-label="Permalink to &quot;Local models&quot;">​</a></h2><p>Ollama, LM Studio and vLLM on your own computer work too: pick the preset (web console: <em>Connections</em>; desktop: <em>Settings → nanoMuse Cloud</em>; phone: <em>Settings → Providers</em>); the address defaults to the local port (<code>http://127.0.0.1:11434/v1</code>, <code>:1234</code>, <code>:8000</code>) and no key is needed. They count as <em>chat</em>; the hands need a model that sees, so run a multimodal one locally (Ollama&#39;s <code>qwen3-vl</code>, say) and pick it under <em>Operating the screen</em> (web console: type its id on the <em>Hands model</em> row). Pictures and clips need one of the providers in the table.</p><h2 id="any-other-openai-compatible-endpoint" tabindex="-1">Any other OpenAI-compatible endpoint <a class="header-anchor" href="#any-other-openai-compatible-endpoint" aria-label="Permalink to &quot;Any other OpenAI-compatible endpoint&quot;">​</a></h2><p>Anything that speaks the OpenAI API works — choose <em>Custom</em>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Base URL</td><td>the provider&#39;s address, usually ending in <code>/v1</code></td></tr><tr><td>API key</td><td>the key made in the provider&#39;s console (a local server may leave it empty)</td></tr><tr><td>Model</td><td>pick from the list after saving; if none appears, type the model id from the provider&#39;s docs</td></tr></tbody></table><p>What a custom endpoint covers is yours to say: nanoMuse takes it for chat, and the hands, picture and clip models count once their ids are filled in.</p>',43)])])}const g=t(r,[["render",s]]);export{m as __pageData,g as default};
